def summary_variable(frame,col,grain,label):
 v=pd.to_numeric(frame[col],errors='coerce').to_numpy(float);good=np.isfinite(v);z=v[good];return dict(variable=label,grain=grain,n=len(z),missing=len(v)-len(z),stocks=frame.code.nunique() if 'code' in frame else 0,events=frame.event_id.nunique() if 'event_id' in frame else len(frame),stock_clusters=frame.code.nunique() if 'code' in frame else 0,date_clusters=frame.date.nunique() if 'date' in frame else (frame.event_id.nunique() if 'event_id' in frame else len(frame)),mean=np.mean(z) if len(z) else np.nan,sd=np.std(z,ddof=1) if len(z)>1 else np.nan,skew=skew(z,bias=False) if len(z)>2 and np.ptp(z)>0 else np.nan,excess_kurtosis=kurtosis(z,bias=False) if len(z)>3 and np.ptp(z)>0 else np.nan,zero_share=np.mean(z==0) if len(z) else np.nan,min=np.min(z) if len(z) else np.nan,max=np.max(z) if len(z) else np.nan,q001=np.quantile(z,.001) if len(z) else np.nan,q01=np.quantile(z,.01) if len(z) else np.nan,q99=np.quantile(z,.99) if len(z) else np.nan,q999=np.quantile(z,.999) if len(z) else np.nan)

